<?php $pageTitle='Create account | HEX CHEATS SHOP';$activePage='account';require __DIR__.'/_head.php'; ?>
<section class="hx-panel hx-auth-panel"><p class="hx-eyebrow">CREATE YOUR ACCOUNT</p><h1>Join HEX CHEATS SHOP</h1><p class="hx-muted">One account keeps your wallet, payment history, orders and delivered keys together.</p><a class="hx-button hx-google" href="/auth/google"><span aria-hidden="true">G</span> Continue with Google</a><div class="hx-divider"><span>or use email</span></div><form id="registerForm" class="hx-form"><label>Display name<input type="text" name="display_name" autocomplete="name" maxlength="100"></label><label>Email<input type="email" name="email" autocomplete="email" required maxlength="254"></label><label>Password<input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="256" required><small>Use at least 10 characters.</small></label><button class="hx-button" type="submit">Create account</button><div class="hx-alert" id="authStatus" role="alert"></div></form><p class="hx-muted">Already registered? <a href="/login">Sign in</a></p></section>
<script>document.getElementById('registerForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),s=document.getElementById('authStatus');s.textContent='';b.disabled=true;try{const r=await fetch('/api/store/register',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:f.display_name.value.trim(),email:f.email.value,password:f.password.value})});const d=await r.json();if(!r.ok)throw Error(d.error||'Registration failed.');location.href='/account'}catch(x){s.textContent=x.message||'Registration failed.'}finally{b.disabled=false}});</script>
